// v0KubernetesRuntimeInstanceUpdated performs reconciliation when a v0 KubernetesRuntimeInstance
// has been updated.
func v0KubernetesRuntimeInstanceUpdated(
	r *controller.Reconciler,
	kubernetesRuntimeInstance *v0.KubernetesRuntimeInstance,
	log *logr.Logger,
) (int64, error) {
	// check to see if we have a valid API endpoint - no further reconciliation
	// can occur until we have that
	if kubernetesRuntimeInstance.APIEndpoint == nil {
		return 0, nil
	}
	parsedEndpoint, parseErr := url.Parse(*kubernetesRuntimeInstance.APIEndpoint)
	if parseErr != nil || parsedEndpoint.Host == "" {
		return 0, nil
	}

	// check to see if kubernetes runtime is being deleted - if so no updates
	// required
	if kubernetesRuntimeInstance.DeletionScheduled != nil {
		return 0, nil
	}

	// get runtime definition
	kubernetesRuntimeDefinition, err := client.GetKubernetesRuntimeDefinitionByID(
		r.APIClient,
		r.APIServer,
		*kubernetesRuntimeInstance.KubernetesRuntimeDefinitionID,
	)
	if err != nil {
		return 0, fmt.Errorf("failed to retrieve kubernetes runtime definition by ID: %w", err)
	}

	// get kube client to install compute space control plane components
	dynamicKubeClient, mapper, err := kube.GetClient(
		kubernetesRuntimeInstance,
		false,
		r.APIClient,
		r.APIServer,
		r.EncryptionKey,
	)
	if err != nil {
		return 0, fmt.Errorf("failed to get a Kubernetes client and mapper: %w", err)
	}

	// TODO: sort out an elegant way to pass the custom image info for
	// install compute space control plane components
	var agentImage string
	if kubernetesRuntimeInstance.ThreeportAgentImage != nil {
		agentImage = *kubernetesRuntimeInstance.ThreeportAgentImage
	}

	cpi := threeport.NewInstaller()

	if agentImage != "" {
		agentRegistry, _, agentTag, err := util.ParseImage(agentImage)
		if err != nil {
			return 0, fmt.Errorf("failed to parse custom threeport agent image: %w", err)
		}

		cpi.Opts.AgentInfo.ImageNamespace = agentRegistry
		cpi.Opts.AgentInfo.ImageTag = agentTag
	}

	// threeport control plane components
	if err := cpi.InstallComputeSpaceControlPlaneComponents(
		dynamicKubeClient,
		mapper,
		*kubernetesRuntimeInstance.Name,
	); err != nil {
		return 0, fmt.Errorf("failed to insall compute space control plane components: %w", err)
	}

	// wait for kube API to persist the change and refresh the client and mapper
	// this is necessary to have the updated REST mapping for the CRDs as the
	// support services operator install includes one of those custom resources
	time.Sleep(time.Second * 10)
	dynamicKubeClient, mapper, err = kube.GetClient(
		kubernetesRuntimeInstance,
		false,
		r.APIClient,
		r.APIServer,
		r.EncryptionKey,
	)
	if err != nil {
		return 0, fmt.Errorf("failed to refresh dynamic kube API client: %w", err)
	}

	// support services operator
	if err := threeport.InstallThreeportSupportServicesOperator(dynamicKubeClient, mapper); err != nil {
		return 0, fmt.Errorf("failed to install support services operator: %w", err)
	}

	if *kubernetesRuntimeDefinition.InfraProvider == v0.KubernetesRuntimeInfraProviderEKS {
		// get aws provider
		awsProvider, err := client.GetAwsProviderByName(
			r.APIClient,
			r.APIServer,
			*kubernetesRuntimeDefinition.InfraProviderAccountName,
		)
		if err != nil {
			return 0, fmt.Errorf("failed to get AWS provider by name: %w", err)
		}

		// system components e.g. cluster-autoscaler
		if err := threeport.InstallEksThreeportSystemServices(
			dynamicKubeClient,
			mapper,
			*kubernetesRuntimeInstance.Name,
			*awsProvider.AccountID,
		); err != nil {
			return 0, fmt.Errorf("failed to install system services: %w", err)
		}
	}

	// On GKE, the control-plane workload controllers authenticate to this
	// managed cluster as their own Workload Identity principals (via per-request
	// ADC tokens), so the managed cluster must grant those principals the access
	// they need to deploy workloads. This mirrors the bindings created on the
	// control-plane cluster in InstallThreeportControllers. It applies only when
	// both this managed cluster and the control-plane host run on GKE; the host
	// instance is skipped because its bindings are created at control-plane
	// install time.
	isControlPlaneHost := kubernetesRuntimeInstance.ThreeportControlPlaneHost != nil &&
		*kubernetesRuntimeInstance.ThreeportControlPlaneHost
	if !isControlPlaneHost &&
		*kubernetesRuntimeDefinition.InfraProvider == v0.KubernetesRuntimeInfraProviderGKE {
		controlPlaneGcpProject, err := controlPlaneGkeProject(r)
		if err != nil {
			return 0, fmt.Errorf("failed to determine control plane GCP project for workload controller RBAC: %w", err)
		}
		if controlPlaneGcpProject != "" {
			if err := cpi.InstallComputeSpaceWorkloadControllerRBAC(
				dynamicKubeClient,
				mapper,
				controlPlaneGcpProject,
			); err != nil {
				return 0, fmt.Errorf("failed to install workload controller RBAC on managed cluster: %w", err)
			}
		}
	}

	return 0, nil
}

// v0KubernetesRuntimeInstanceDeleted performs reconciliation when a v0 KubernetesRuntimeInstance
// has been deleted.
func v0KubernetesRuntimeInstanceDeleted(
	r *controller.Reconciler,
	kubernetesRuntimeInstance *v0.KubernetesRuntimeInstance,
	log *logr.Logger,
) (int64, error) {
	// check that deletion is scheduled - if not there's a problem
	if kubernetesRuntimeInstance.DeletionScheduled == nil {
		return 0, errors.New("deletion notification receieved but not scheduled")
	}

	// check to see if deletion confirmed - it should not be, but if so we should do no
	// more
	if kubernetesRuntimeInstance.DeletionConfirmed != nil {
		return 0, nil
	}

	// get runtime definition
	kubernetesRuntimeDefinition, err := client.GetKubernetesRuntimeDefinitionByID(
		r.APIClient,
		r.APIServer,
		*kubernetesRuntimeInstance.KubernetesRuntimeDefinitionID,
	)
	if err != nil {
		return 0, fmt.Errorf("failed to retrieve kubernetes runtime definition by ID: %w", err)
	}

	// TODO: delete support services svc to elliminate ELB

	// delete kubernetes runtime instance
	switch *kubernetesRuntimeDefinition.InfraProvider {
	case v0.KubernetesRuntimeInfraProviderEKS:
		// get AWS EKS runtime instance
		awsEksKubernetesRuntimeInstance, err := client.GetAwsEksKubernetesRuntimeInstanceByK8sRuntimeInst(
			r.APIClient,
			r.APIServer,
			*kubernetesRuntimeInstance.ID,
		)
		if err != nil {
			return 0, fmt.Errorf("failed to get aws eks runtime instance by kubernetes runtime instance ID: %w", err)
		}

		// delete AWS EKS runtime instance
		_, err = client.DeleteAwsEksKubernetesRuntimeInstance(
			r.APIClient,
			r.APIServer,
			*awsEksKubernetesRuntimeInstance.ID,
		)
		if err != nil {
			return 0, fmt.Errorf("failed to delete aws eks runtime instance by ID: %w", err)
		}
	case v0.KubernetesRuntimeInfraProviderGKE:
		// get GCP GKE runtime instance
		gcpGkeKubernetesRuntimeInstance, err := client.GetGcpGkeKubernetesRuntimeInstanceByK8sRuntimeInst(
			r.APIClient,
			r.APIServer,
			*kubernetesRuntimeInstance.ID,
		)
		if err != nil {
			if errors.Is(err, client_lib.ErrObjectNotFound) {
				// GcpGke instance already gone - nothing left to delete
				return 0, nil
			}
			return 0, fmt.Errorf("failed to get GCP GKE runtime instance by kubernetes runtime instance ID: %w", err)
		}

		// delete GCP GKE runtime instance
		_, err = client.DeleteGcpGkeKubernetesRuntimeInstance(
			r.APIClient,
			r.APIServer,
			*gcpGkeKubernetesRuntimeInstance.ID,
		)
		if err != nil {
			return 0, fmt.Errorf("failed to delete GCP GKE runtime instance by ID: %w", err)
		}
	}

	return 0, nil
}

// controlPlaneGkeProject returns the GCP project ID of the GKE cluster hosting
// the threeport control plane, or "" if the control plane is not hosted on GKE.
// It is used to construct the Workload Identity principals of the control-plane
// controllers when granting them access to managed clusters. The control-plane
// host is the KubernetesRuntimeInstance marked ThreeportControlPlaneHost.
func controlPlaneGkeProject(r *controller.Reconciler) (string, error) {
	instances, err := client.GetKubernetesRuntimeInstances(r.APIClient, r.APIServer)
	if err != nil {
		return "", fmt.Errorf("failed to list kubernetes runtime instances: %w", err)
	}

	var hostInstance *v0.KubernetesRuntimeInstance
	for i := range *instances {
		if (*instances)[i].ThreeportControlPlaneHost != nil && *(*instances)[i].ThreeportControlPlaneHost {
			hostInstance = &(*instances)[i]
			break
		}
	}
	if hostInstance == nil {
		return "", fmt.Errorf("no control plane host kubernetes runtime instance found")
	}

	hostDefinition, err := client.GetKubernetesRuntimeDefinitionByID(
		r.APIClient,
		r.APIServer,
		*hostInstance.KubernetesRuntimeDefinitionID,
	)
	if err != nil {
		return "", fmt.Errorf("failed to get control plane host runtime definition: %w", err)
	}

	// Only GKE-hosted control planes present Workload Identity principals to
	// managed clusters; for any other host provider there is no WI principal to
	// bind, so signal "not applicable" with an empty project.
	if hostDefinition.InfraProvider == nil ||
		*hostDefinition.InfraProvider != v0.KubernetesRuntimeInfraProviderGKE {
		return "", nil
	}
	if hostDefinition.InfraProviderAccountName == nil {
		return "", fmt.Errorf("control plane host runtime definition has no infra provider account name")
	}

	gcpProvider, err := client.GetGcpProviderByName(
		r.APIClient,
		r.APIServer,
		*hostDefinition.InfraProviderAccountName,
	)
	if err != nil {
		return "", fmt.Errorf("failed to get GCP provider %q: %w", *hostDefinition.InfraProviderAccountName, err)
	}
	if gcpProvider.ProjectID == nil {
		return "", fmt.Errorf("GCP provider %q has no project ID", *hostDefinition.InfraProviderAccountName)
	}

	return *gcpProvider.ProjectID, nil
}

// GetCloudProviderForInfraProvider returns the cloud provider for a given
// infrastructure provider.
func GetCloudProviderForInfraProvider(input string) (string, error) {
	switch input {
	case v0.KubernetesRuntimeInfraProviderEKS:
		return util.AwsProvider, nil
	case v0.KubernetesRuntimeInfraProviderGKE:
		return util.GcpProvider, nil
	case v0.KubernetesRuntimeInfraProviderKind:
		return util.AwsProvider, nil // default to AWS values for testing purposes
	default:
		return "", fmt.Errorf("failed to get provider, infra provider %s not supported", input)
	}
}
